import {art,image,esc,action,heading} from '../homepage/ui.js';
import {header,footer} from '../homepage/sections.js';
import {propertyCard} from '../homepage/cards.js';
import {searchFields} from '../homepage/search-fields.js';
import {catalogData} from './data.js';

export function catalogHeader(){return header({light:true,contactDetails:catalogData.contacts,linkBase:'homepage.html'});}
export function catalogFooter(){return footer(catalogData.footer,{contactDetails:catalogData.contacts,linkBase:'homepage.html'});}
const range=(name,label,unit='')=>`<fieldset class="filter-range range-${name.toLowerCase()}"><legend>${label}${unit?`, ${unit}`:''}:</legend><label><span class="visually-hidden">${label} от</span><input name="min${name}" type="number" min="0" step="${name==='Floor'?'1':'any'}" inputmode="decimal" placeholder="от"></label><label><span class="visually-hidden">${label} до</span><input name="max${name}" type="number" min="0" step="${name==='Floor'?'1':'any'}" inputmode="decimal" placeholder="до"></label></fieldset>`;
export function catalogFilter(){return `<form id="catalog-filter" class="catalog-filter" aria-label="Подбор недвижимости">
 ${searchFields()}
 <div class="filter-ranges">${range('Price','Цена','руб.')}${range('Area','Площадь','м²')}<label class="renovation"><input type="checkbox" role="switch" name="renovated"><span aria-hidden="true"></span>С ремонтом</label></div>
 <details class="extra-filters"><summary>Ещё фильтры <span aria-hidden="true">+</span></summary><div class="extra-filter-fields">${range('Floor','Этаж')}<label class="wall-filter">Стены<select name="walls" aria-label="Материал стен"><option value="">Любые</option><option>Монолит</option><option>Панель</option><option>Кирпич</option></select></label></div></details>
 <div class="filter-actions"><button type="reset" class="pill filter-reset">Сбросить <span aria-hidden="true">×</span></button><button type="button" class="pill outline" data-map>На карте</button><button type="submit" class="pill filter-submit">Показать 20 объектов</button></div><p class="filter-error" role="alert" hidden></p>
 </form>`;}
export function mapStrip(){return `<div class="map-strip"><img src="${esc(catalogData.mapImage)}" alt="" class="map-crop" width="3562" height="2020"><button type="button" class="pill map-button" data-map>Показать на карте</button></div>`;}
export function developmentBanner(){return `<aside class="development-banner" aria-label="Квартиры в новостройках"><div class="banner-image">${image(catalogData.bannerImage,'','','loading="lazy"')}</div><div class="banner-copy"><p class="eyebrow">Без комиссии</p><h2>Квартиры в новостройках<span>76 предложений</span></h2></div><span class="banner-zero" aria-hidden="true">0</span><a href="property-catalog.html?market=new" class="banner-link" aria-label="Посмотреть новостройки в каталоге"></a>${image(art('blue_romb_blur.svg'),'','banner-decoration','loading="lazy"')}</aside>`;}
export function resultCards(items,{banner=true}={}){return items.map((item,index)=>`${index===12&&banner?developmentBanner():''}${propertyCard(item)}`).join('');}
export function results(){return `<section class="catalog-results" id="catalog-results" aria-labelledby="results-count" tabindex="-1"><div class="results-toolbar"><h2 id="results-count" aria-live="polite">Найдено 20 объектов</h2><div class="catalog-sort"><span>Сортировать:</span><button type="button" data-sort="source" aria-pressed="true">по дате добавления <span aria-hidden="true">↓</span></button><button type="button" data-sort="price" aria-pressed="false">по цене <span class="price-direction" aria-hidden="true"></span></button></div></div><div id="catalog-cards" class="property-grid">${resultCards(catalogData.properties)}</div><div class="catalog-empty" hidden><h3>По вашему запросу ничего не найдено</h3><p>Попробуйте изменить условия поиска.</p><button type="button" class="pill outline" data-clear>Сбросить фильтры</button></div><div class="catalog-pagination"><label>На странице<select name="pageSize" aria-label="Объектов на странице"><option value="20">20</option><option value="12">12</option></select></label><p class="page-status">20 из 20 объектов</p><nav id="catalog-pages" aria-label="Страницы каталога"><button type="button" data-page="1" aria-current="page">1</button></nav></div></section>`;}
export function helpSection(){const help=catalogData.help;return `<section class="purchase-help" id="purchase-help">${heading(esc(help.eyebrow),esc(help.title))}<div class="help-lead"><p>${esc(help.lead)}</p>${action('Оставить заявку')}</div><div class="help-body"><p>${esc(help.body)}</p></div></section>`;}
export function pageContent(){return `${catalogHeader()}<main id="catalog-page"><div class="container"><nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="homepage.html">Главная</a><span aria-hidden="true">/</span><a href="property-catalog.html">Недвижимость</a><span aria-hidden="true">/</span><span aria-current="page">Квартиры</span></nav><h1>${esc(catalogData.title)}</h1>${catalogFilter()}${mapStrip()}${results()}${helpSection()}</div></main>${catalogFooter()}`;}
